#include <iostream>
#include <sstream>
#include <string>

enum class Resultado {
    aceptada,
    sin_datos,
    formato_invalido,
    adicionales,
    fuera_de_dominio,
    capacidad_invalida
};

Resultado aplicar_linea(const std::string& texto, int& ocupadas) {
    std::istringstream presencia{texto};
    std::string primera;
    if (!(presencia >> primera)) {
        if (presencia.bad() || !presencia.eof()) {
            return Resultado::formato_invalido;
        }
        return Resultado::sin_datos;
    }

    std::istringstream campos{texto};
    int entran = 0;
    char separador = ' ';
    int salen = 0;
    if (!(campos >> entran >> separador >> salen) || separador != ':') {
        return Resultado::formato_invalido;
    }

    std::string extra;
    if (campos >> extra) {
        return Resultado::adicionales;
    }

    if (campos.bad() || !campos.eof()) {
        return Resultado::formato_invalido;
    }

    if (entran < 0 || entran > 3 || salen < 0 || salen > 3) {
        return Resultado::fuera_de_dominio;
    }

    const int candidata = ocupadas + entran - salen;
    if (candidata < 0 || candidata > 6) {
        return Resultado::capacidad_invalida;
    }

    ocupadas = candidata;
    return Resultado::aceptada;
}

std::string mensaje(Resultado resultado) {
    if (resultado == Resultado::aceptada) {
        return "Aceptada";
    }

    if (resultado == Resultado::sin_datos) {
        return "Sin datos";
    }

    if (resultado == Resultado::formato_invalido) {
        return "Formato invalido";
    }

    if (resultado == Resultado::adicionales) {
        return "Datos adicionales";
    }

    if (resultado == Resultado::fuera_de_dominio) {
        return "Fuera de dominio";
    }
    return "Capacidad invalida";
}

int main() {
    int ocupadas = 3;
    int aceptadas = 0;
    std::string linea;

    while (std::getline(std::cin, linea)) {
        const Resultado resultado = aplicar_linea(linea, ocupadas);

        if (resultado == Resultado::aceptada) {
            ++aceptadas;
        }

        std::cout << mensaje(resultado) << " | Ocupadas: " << ocupadas << "\n";
    }

    if (std::cin.bad() || !std::cin.eof()) {
        std::cout << "Fallo del origen\n";
        return 1;
    }

    std::cout << "Aceptadas: " << aceptadas << "\n";
    std::cout << "Ocupadas: " << ocupadas << "\n";

    return 0;
}

